-- Jalankan pada Supabase SQL Editor; aplikasi menggunakan RPC SECURITY DEFINER terkontrol.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',role text not null default 'CUSTOMER' check(role in('SUPER_ADMIN','SUPERVISOR','HELP_DESK','TECHNICIAN','NOC_ENGINEER','CUSTOMER')),created_at timestamptz not null default now());
create table if not exists public.tickets(id uuid primary key default gen_random_uuid(),ticket_number text not null unique,customer_id uuid not null references public.profiles(id),assigned_to uuid references public.profiles(id),subject varchar(160) not null,description text not null,category text not null,priority text not null check(priority in('LOW','MEDIUM','HIGH','CRITICAL')),status text not null default 'NEW' check(status in('NEW','OPEN','ASSIGNED','IN_PROGRESS','PENDING','ESCALATED','RESOLVED','REOPENED','CLOSED','CANCELLED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ticket_activities(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.tickets(id),actor_id uuid not null references public.profiles(id),from_status text,to_status text not null,note text not null default '',created_at timestamptz not null default now());
create sequence if not exists public.ticket_number_seq;
create index if not exists idx_tickets_customer on public.tickets(customer_id,created_at desc);
create index if not exists idx_tickets_assignee on public.tickets(assigned_to,created_at desc);
create index if not exists idx_tickets_status on public.tickets(status,created_at desc);
create index if not exists idx_activity_ticket on public.ticket_activities(ticket_id,created_at desc);
create or replace function public.create_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.create_profile();
insert into public.profiles(id,full_name) select id,coalesce(raw_user_meta_data->>'full_name','') from auth.users on conflict(id) do nothing;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=(select auth.uid()) and role in('SUPER_ADMIN','SUPERVISOR','HELP_DESK'))$$;
create or replace function public.can_access_ticket(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.tickets where id=p_id and (customer_id=(select auth.uid()) or assigned_to=(select auth.uid()) or public.is_staff()))$$;
alter table public.profiles enable row level security;
alter table public.tickets enable row level security;
alter table public.ticket_activities enable row level security;
drop policy if exists profile_select on public.profiles;
create policy profile_select on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_staff());
drop policy if exists ticket_select on public.tickets;
create policy ticket_select on public.tickets for select to authenticated using(customer_id=(select auth.uid()) or assigned_to=(select auth.uid()) or public.is_staff());
drop policy if exists activity_select on public.ticket_activities;
create policy activity_select on public.ticket_activities for select to authenticated using(public.can_access_ticket(ticket_id));
-- Tidak ada kebijakan write langsung: mutasi hanya lewat RPC terverifikasi.
create or replace function public.create_ticket(p_subject text,p_description text,p_category text,p_priority text) returns uuid language plpgsql security definer set search_path='' as $$declare v_id uuid;v_user uuid;v_number text;begin v_user:=auth.uid();if v_user is null then raise exception 'Login diperlukan';end if;if length(trim(p_subject))<3 or length(p_subject)>160 or length(trim(p_description))<10 or length(p_description)>10000 then raise exception 'Subjek atau deskripsi tidak valid';end if;if p_priority not in('LOW','MEDIUM','HIGH','CRITICAL') or p_category not in('Internet','LAN','WiFi','Router','Switch','Server','Komputer','Printer','Software','Keamanan Jaringan','Lainnya') then raise exception 'Kategori atau prioritas tidak valid';end if;v_number:='HD-'||to_char(now() at time zone 'UTC','YYYY')||'-'||lpad(nextval('public.ticket_number_seq')::text,6,'0');insert into public.tickets(ticket_number,customer_id,subject,description,category,priority) values(v_number,v_user,trim(p_subject),trim(p_description),p_category,p_priority) returning id into v_id;insert into public.ticket_activities(ticket_id,actor_id,to_status,note) values(v_id,v_user,'NEW','Tiket dibuat');return v_id;end$$;
create or replace function public.assign_ticket(p_ticket_id uuid,p_assignee uuid,p_note text default '') returns void language plpgsql security definer set search_path='' as $$declare v_ticket public.tickets%rowtype;begin if not public.is_staff() then raise exception 'Tidak berwenang';end if;if not exists(select 1 from public.profiles where id=p_assignee and role in('TECHNICIAN','NOC_ENGINEER')) then raise exception 'Petugas tidak valid';end if;select * into v_ticket from public.tickets where id=p_ticket_id for update;if not found or v_ticket.status not in('OPEN','REOPENED','NEW','ASSIGNED') then raise exception 'Tiket tidak dapat didelegasikan';end if;update public.tickets set assigned_to=p_assignee,status='ASSIGNED',updated_at=now() where id=p_ticket_id;insert into public.ticket_activities(ticket_id,actor_id,from_status,to_status,note) values(p_ticket_id,auth.uid(),v_ticket.status,'ASSIGNED',coalesce(p_note,'')||' (penugasan)');end$$;
create or replace function public.transition_ticket(p_ticket_id uuid,p_next text,p_note text default '') returns void language plpgsql security definer set search_path='' as $$declare v_ticket public.tickets%rowtype;v_role text;v_allowed boolean:=false;begin if auth.uid() is null then raise exception 'Login diperlukan';end if;select * into v_ticket from public.tickets where id=p_ticket_id for update;if not found then raise exception 'Tiket tidak ditemukan';end if;select role into v_role from public.profiles where id=auth.uid();if v_role in('SUPER_ADMIN','SUPERVISOR','HELP_DESK') then v_allowed:= (v_ticket.status='NEW' and p_next in('OPEN','CANCELLED')) or (v_ticket.status='RESOLVED' and p_next in('CLOSED','REOPENED')) or (v_ticket.status='REOPENED' and p_next='OPEN') or (v_ticket.status='ESCALATED' and p_next='OPEN');elsif v_role in('TECHNICIAN','NOC_ENGINEER') and v_ticket.assigned_to=auth.uid() then v_allowed:=(v_ticket.status='ASSIGNED' and p_next='IN_PROGRESS') or (v_ticket.status='IN_PROGRESS' and p_next in('PENDING','ESCALATED','RESOLVED')) or (v_ticket.status='PENDING' and p_next='IN_PROGRESS');elsif v_role='CUSTOMER' and v_ticket.customer_id=auth.uid() then v_allowed:=v_ticket.status='RESOLVED' and p_next='REOPENED';end if;if not v_allowed then raise exception 'Transisi status tidak diizinkan';end if;if p_next in('CANCELLED','PENDING','ESCALATED','RESOLVED','REOPENED') and length(trim(coalesce(p_note,'')))<10 then raise exception 'Catatan minimal 10 karakter diperlukan';end if;update public.tickets set status=p_next,updated_at=now() where id=p_ticket_id;insert into public.ticket_activities(ticket_id,actor_id,from_status,to_status,note) values(p_ticket_id,auth.uid(),v_ticket.status,p_next,coalesce(p_note,''));end$$;
revoke all on function public.is_staff() from public;
revoke all on function public.can_access_ticket(uuid) from public;
revoke all on function public.create_ticket(text,text,text,text) from public;
revoke all on function public.assign_ticket(uuid,uuid,text) from public;
revoke all on function public.transition_ticket(uuid,text,text) from public;
grant execute on function public.is_staff() to authenticated;
grant execute on function public.can_access_ticket(uuid) to authenticated;
grant execute on function public.create_ticket(text,text,text,text) to authenticated;
grant execute on function public.assign_ticket(uuid,uuid,text) to authenticated;
grant execute on function public.transition_ticket(uuid,text,text) to authenticated;
